"""Colab exam briefing content, applied after general lesson generators."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def slide(title,body,notes,kind='steps'):
 return dict(title=title,body=body,notes=notes,kind=kind,colab_exam_revision='2026.10-v1')
def revise(decks):
 for d in decks:
  if d['week'] not in (7,14):continue
  exam='TEST1' if d['week']==7 else 'TEST2'
  from test_revision_slides import revision_slides
  keep = revision_slides(d)
  added=[
   slide('Your test files on test day','Downloads unlock at the scheduled start time. Open the link or scan its QR code.\n\nEnter your name, Google email and Student Registration Number.\n\nDownload your notebook and engineering_data.csv.','The page assigns files automatically. Students do not choose a version. Re-entering the same registration number and Google email retrieves the same allocation. The page can be opened in advance, but downloads are available only during the authorised test window. A phone scan is useful for opening the page, but students must download and use both files on their laptop. Students never choose a test version.'),
   slide('Opening the notebook and CSV','In Colab: File → Open notebook → Upload. Select the downloaded notebook.\n\nSave a copy in Drive. Connect the session.\n\nIn Files on the left, upload engineering_data.csv.','A notebook upload does not include its data. Show the folder icon, then Upload. Wait until engineering_data.csv appears. Do not upload a ZIP. The portal prefills the identity cell; students check it and run it before later cells. The final submission cell contains an internal allocation code and is collapsed for clarity. Keep it unchanged.'),
   slide('One notebook contains all answers','Code tasks have a prompt, function name and marks.\n\nSix interpretation questions: record your chosen option letters in DECISIONS.\n\nSubmit one notebook snapshot using the final button.','A function is a named block of code. The grader calls that function with different records, so it must calculate from its argument. DECISIONS is a dictionary pairing each question identifier with one option letter. Use a non-assessed demonstration such as {"practice": "B"}. No separate report or prose answer section is required.'),
   slide('How the 100 marks are allocated',('Cleaning 20. Summary statistics 15.\n\nThree labelled charts 15. Five numerical findings 20.\n\nStructured interpretation 30.' if exam=='TEST1' else 'Equipment-group split 20.\n\nBaseline, linear and tree predictions 30.\n\nMAE and RMSE 20. Structured interpretation 30.'),'Explain that all marks come from the published checks. Correct code on unseen inputs earns coding marks. Each of the six interpretation choices earns 5 marks. Test 1 contributes 15 points and Test 2 contributes 20 points to the semester total. For example, 80/100 in Test 1 contributes 12 semester points. Partial marks are available for independently checked outputs; charts and cleaning each have a complete contract.'),
   slide('Order of work',('Load the raw CSV. Keep the original data.\n\nClean records before calculating summaries, charts and findings.\n\nAnswer the six interpretation questions.' if exam=='TEST1' else 'Run the supplied row filters, then split by equipment ID.\n\nFit the imputer and models on training records only.\n\nCompare validation errors. Keep the specified final-test group untouched.'),'Test 1: duplicate removal keeps the first occurrence. Exclude a missing target or invalid load. Only then calculate the retained ambient median. Test 2: row filters are supplied, but missing ambient values remain. A pipeline learns the median from the training partition and reuses it for validation. Fitting a median on all rows leaks evaluation information. Do not reveal assessed option answers during the test.'),
   slide('The three-hour session','First 15 minutes: setup and file checks.\n\nNext 120 minutes: individual coding tasks.\n\nNext 25 minutes: interpretation and checking.\n\nFinal 20 minutes: prepare the snapshot and submit the form.','Announce the actual start and close time displayed by the form. These periods total 180 minutes. Code execution is allowed during checking. Report internet or runtime problems immediately. Record incidents with the affected learner and time. Do not silently treat a failed upload as a submitted test.'),
   slide('Before submitting','Restart the Colab session and run cells from the top.\n\nUpload the same CSV again if the new session needs it.\n\nFix errors and run the final submission cell.','A fresh session has no variables from earlier runs. This exposes cells that depend on stale values or an incorrect order. The supplied CSV example cell calls the implemented functions. The final submission cell creates a button. Clicking it prepares a separate snapshot of the current notebook in Drive; later edits to the working notebook do not change that snapshot. Students must open the generated form link and press Submit. The button alone is not a completed submission.'),
   slide('Submission and confirmation','Click Submit test at the end of your notebook.\n\nOpen the generated form link using the same Google account. Check your details.\n\nPress Submit before the deadline. Keep the confirmation.','Demonstrate the final button using a rehearsal notebook. The button privately shares a saved snapshot with the lecturer and fills the form fields. Tick the form’s email confirmation box before pressing Submit. Do not type snapshot IDs manually. The form records the verified Google email; it must be the same account that owns the snapshot. A new attempt requires clicking the notebook button again and submitting its new form link. The latest on-time attempt is considered; technical or identity errors remain pending. Earlier attempts are retained.'),
   slide('How grading works','The lecturer’s grader runs your submitted code on unseen data.\n\nThe private workbook records identity, submission time, status and marks.\n\nA technical or identity problem remains pending until resolved.','Grades are calculated in a batch on the lecturer’s Mac after the test. The Mac can be off during submission. Google Forms and Drive collect the snapshots. Before admitting students, rehearse the entry page, two downloads, notebook button and form confirmation. After the test, export the batch and run Grade_Tests.command with Docker running. A receipt is not a grade. A genuine zero is distinct from pending or infrastructure failure. The attendee register is built from submissions; without an enrolled roster it cannot identify absentees.')]
  portal_path=ROOT/'data/test_portal_config.json'
  if portal_path.exists():
   config=json.loads(portal_path.read_text());entry=config['links'][d['cohort']+'|'+exam]
   added[0].update(kind='test_entry',url=entry,label='Open your test files',qr='qr/test_entry/'+d['cohort']+'_'+exam+'.png')
  d['slides']=keep+added;d['colab_exam_revision']='2026.10-v1'
  for i,s in enumerate(d['slides'],1):s['sequence_number']=i
 return decks
if __name__=='__main__':
 p=ROOT/'data/iuea_deck_content.json';p.write_text(json.dumps(revise(json.loads(p.read_text())),indent=2,ensure_ascii=False)+'\n')
